"""Annualize volatility over trading days (RISK-03)."""

from __future__ import annotations

import dataclasses
import math

from risk.types import VolSeries


def annualize(vol: VolSeries, periods_per_year: int = 252) -> VolSeries:
    """Scale each daily volatility by sqrt(periods_per_year), keeping gaps (None) as gaps.

    Raises ValueError if `vol` is already annualized.
    """
    if vol.annualized:
        raise ValueError(f"volatility is already annualized ({periods_per_year} periods/year)")
    scale = math.sqrt(periods_per_year)
    values = {
        ticker: tuple(None if v is None else v * scale for v in series)
        for ticker, series in vol.values.items()
    }
    return dataclasses.replace(vol, annualized=True, values=values)

